add_action( 'woocommerce_before_order_notes', 'perfectpixel_custom_field_render' );
add_action( 'woocommerce_checkout_process', 'perfectpixel_custom_field_validate' );
add_action( 'woocommerce_checkout_create_order', 'perfectpixel_custom_field_save', 10, 2 );
add_action( 'woocommerce_admin_order_data_after_billing_address', 'perfectpixel_custom_field_show' );
add_action( 'woocommerce_order_details_after_order_table', 'perfectpixel_custom_field_show' );
add_action( 'woocommerce_email_after_order_table', 'perfectpixel_custom_field_show' );

function perfectpixel_custom_field_required() {
	return true;
}

function perfectpixel_custom_field_render( $checkout ) {
	woocommerce_form_field(
		'perfectpixel_custom_field',
		array(
			'type'     => 'text',
			'label'    => '{{custom_field_label}}',
			'required' => perfectpixel_custom_field_required(),
			'class'    => array( 'form-row-wide' ),
		),
		$checkout->get_value( 'perfectpixel_custom_field' )
	);
}

function perfectpixel_custom_field_validate() {
	$value = isset( $_POST['perfectpixel_custom_field'] ) ? trim( wp_unslash( $_POST['perfectpixel_custom_field'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification, WordPress.Security.ValidatedSanitizedInput
	if ( perfectpixel_custom_field_required() && '' === $value ) {
		wc_add_notice( esc_html( '{{custom_field_error}}' ), 'error' );
	}
}

function perfectpixel_custom_field_save( $order, $data ) {
	if ( ! empty( $_POST['perfectpixel_custom_field'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		$order->update_meta_data( '_perfectpixel_custom_field', sanitize_text_field( wp_unslash( $_POST['perfectpixel_custom_field'] ) ) ); // phpcs:ignore WordPress.Security.NonceVerification
	}
}

function perfectpixel_custom_field_show( $order ) {
	if ( ! $order instanceof WC_Order ) {
		return;
	}
	$value = $order->get_meta( '_perfectpixel_custom_field' );
	if ( '' !== (string) $value ) {
		printf( '<p><strong>%s:</strong> %s</p>', esc_html( '{{custom_field_label}}' ), esc_html( $value ) );
	}
}
